'use strict';
// Tiny zero-dependency CommonJS bundler. Walks the require() graph from an entry
// module (static string-literal requires only, relative paths), and emits a
// self-contained IIFE that assigns the entry's exports to a global. Used to
// build web/ringdater.bundle.js for the standalone Quick Chronology Checker page
// (the ringdater-js library is CommonJS; no npm bundler is available offline).
//
//   node tools/bundle.js <entry.js> <out.js> <globalName>

const fs = require('fs');
const path = require('path');

// Defaults build the main library bundle; override via CLI args for other entries.
const ROOT = path.resolve(__dirname, '..');
const entry = path.resolve(process.argv[2] || path.join(ROOT, 'src/engine/browserEntry.js'));
const outPath = path.resolve(process.argv[3] || path.join(ROOT, 'web/ringdater.bundle.js'));
const globalName = process.argv[4] || 'RD';

// Node core modules that are NOT available in the browser. When a bundled module
// require()s one of these (e.g. src/io/xlsx.js -> require('zlib')), we don't fail
// the build — instead we register a STUB module. The stub is a plain object whose
// every property is a function that throws a clear message. This is safe because
// these modules are only pulled in transitively (loaders.js -> xlsx.js) and their
// APIs are called lazily (xlsx reading), never at module-load time. So the CSV /
// RWL / .pos / .lps / Ring-Measurer loaders bundle & run fine; only .xlsx reading
// throws (the UI marks .xlsx as needing a shim).
const EXTERNALS = new Set(['zlib', 'fs', 'path', 'crypto', 'buffer', 'util', 'stream', 'os', 'assert']);
function externalName(request) { return request.replace(/^node:/, ''); }
function isExternal(request) { return EXTERNALS.has(externalName(request)); }

const externals = {};     // extKey ('ext:zlib') -> request name (for stub message)

function resolve(from, request) {
  let p = path.resolve(path.dirname(from), request);
  const tries = [p, p + '.js', path.join(p, 'index.js')];
  for (const t of tries) { if (fs.existsSync(t) && fs.statSync(t).isFile()) return t; }
  throw new Error('bundle: cannot resolve "' + request + '" from ' + from);
}

const modules = {};       // absPath -> { code, deps: { request -> target(absPath|extKey) } }
const REQ_RE = /require\(\s*(['"])((?:\\.|(?!\1).)*)\1\s*\)/g;

function addModule(abs) {
  if (modules[abs]) return;
  const src = fs.readFileSync(abs, 'utf8');
  const deps = {};
  let m;
  REQ_RE.lastIndex = 0;
  while ((m = REQ_RE.exec(src)) !== null) {
    const request = m[2];
    if (!request.startsWith('.') && !request.startsWith('/')) {
      if (isExternal(request)) {
        const key = 'ext:' + externalName(request);
        externals[key] = externalName(request);
        deps[request] = key;               // resolved to a stub, not a file
        continue;
      }
      throw new Error('bundle: non-relative require("' + request + '") in ' + abs + ' (not supported)');
    }
    const target = resolve(abs, request);
    deps[request] = target;
  }
  modules[abs] = { code: src, deps };
  for (const request of Object.keys(deps)) {
    const t = deps[request];
    if (typeof t === 'string' && t.startsWith('ext:')) continue;
    addModule(t);
  }
}

addModule(entry);

const keys = Object.keys(modules);
const id = {};
keys.forEach((k, i) => { id[k] = 'm' + i; });

// define-key for a dependency target: external stubs use their 'ext:*' key
// verbatim; real modules use their generated 'm<i>' id.
function defineKey(target) {
  return (typeof target === 'string' && target.startsWith('ext:')) ? target : id[target];
}

let out = '';
out += '/* AUTO-GENERATED by tools/bundle.js — do not edit. */\n';
out += '(function(global){\n';
out += '  var registry = {};\n';
out += '  function define(key, deps, fn){ registry[key] = { deps: deps, fn: fn, mod: null }; }\n';
out += '  function req(key){\n';
out += '    var e = registry[key];\n';
out += '    if (e.mod) return e.mod.exports;\n';
out += '    var module = { exports: {} }; e.mod = module;\n';
out += '    var localReq = function(r){ var t = e.deps[r]; if(!t) throw new Error("bundle: unresolved require "+r); return req(t); };\n';
out += '    e.fn(module, module.exports, localReq);\n';
out += '    return module.exports;\n';
out += '  }\n';

// Stub defines for Node core modules absent in the browser (see EXTERNALS note).
for (const key of Object.keys(externals)) {
  const name = externals[key];
  out += '  define(' + JSON.stringify(key) + ', {}, function(module, exports, require){\n';
  out += '    var msg = "ringdater: Node module \\"' + name + '\\" is not available in the browser bundle.' +
         ' (.xlsx reading needs a zlib shim — use CSV/TXT/RWL/.pos/.lps instead.)";\n';
  out += '    module.exports = new Proxy({}, { get: function(){ return function(){ throw new Error(msg); }; } });\n';
  out += '  });\n';
}

for (const k of keys) {
  const mod = modules[k];
  const depMap = Object.keys(mod.deps).map(r => JSON.stringify(r) + ':' + JSON.stringify(defineKey(mod.deps[r]))).join(',');
  out += '  define(' + JSON.stringify(id[k]) + ', {' + depMap + '}, function(module, exports, require){\n';
  out += mod.code + '\n';
  out += '  });\n';
}

out += '  global[' + JSON.stringify(globalName) + '] = req(' + JSON.stringify(id[entry]) + ');\n';
out += '})(typeof window !== "undefined" ? window : this);\n';

fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, out);
console.log('bundled', keys.length, 'modules ->', outPath, '(' + out.length + ' bytes)');
